1	import type { FastifyInstance } from 'fastify'
2	import pdfParse from 'pdf-parse'
3	import { claudeClient } from '../services/claudeClient'
4	
5	interface PDFAnalysisResult {
6	  score: number
7	  explanation: string
8	  key_points: string[]
9	}
10	
11	export async function pdfRoute(app: FastifyInstance) {
12	  app.post('/api/pdf', async (request, reply) => {
13	    const parts = request.parts()
14	
15	    let persona = ''
16	    let fileBuffer: Buffer | null = null
17	
18	    for await (const part of parts) {
19	      if (part.type === 'field' && part.fieldname === 'persona') {
20	        persona = part.value as string
21	      } else if (part.type === 'file' && part.fieldname === 'file') {
22	        const chunks: Buffer[] = []
23	        for await (const chunk of part.file) {
24	          chunks.push(chunk)
25	        }
26	        fileBuffer = Buffer.concat(chunks)
27	      }
28	    }
29	
30	    if (!fileBuffer) {
31	      return reply.status(400).send({ error: 'No file uploaded' })
32	    }
33	
34	    if (!persona) {
35	      return reply.status(400).send({ error: 'persona field required' })
36	    }
37	
38	    const { text } = await pdfParse(fileBuffer)
39	    const truncatedText = text.slice(0, 4000)
40	
41	    const response = await claudeClient.messages.create({
42	      model: 'claude-sonnet-4-6',
43	      max_tokens: 512,
44	      messages: [
45	        {
46	          role: 'user',
47	          content: `You are reviewing a document for relevance to a specific person.
48	
49	Person: ${persona}
50	
51	Document text:
52	${truncatedText}
53	
54	Rate how relevant this document is to this person's situation on a scale of 1–10.
55	
56	Return ONLY a JSON object (no markdown):
57	{
58	  "score": 7,
59	  "explanation": "One paragraph explaining relevance.",
60	  "key_points": ["point 1", "point 2", "point 3"]
61	}`,
62	        },
63	      ],
64	    })
65	
66	    const textBlock = response.content.find((b) => b.type === 'text')
67	    let result: PDFAnalysisResult
68	    try {
69	      const raw = (textBlock?.type === 'text' ? textBlock.text : '{}')
70	        .replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim()
71	      result = JSON.parse(raw)
72	    } catch {
73	      result = { score: 0, explanation: 'Could not parse document', key_points: [] }
74	    }
75	
76	    return result
77	  })
78	}
